N = 1005
mat = [[''] * N for _ in range(N)]
a = [[0] * N for _ in range(N)]
d = [(-1, 0), (1, 0), (0, -1), (0, 1)]
n, m = map(int, input().split())
for i in range(1, n + 1):
    line = input().strip()
    for j in range(1, m + 1):
        mat[i][j] = line[j - 1]
ans = 0
for i in range(1, n + 1):
    for j in range(1, m + 1):
        num = 0
        p = -1

        for k in range(4):
            ni, nj = i + d[k][0], j + d[k][1]
            if mat[ni][nj] == '#':
                num += 1
                p = k

        if mat[i][j] == '.' and num == 1:
            ni, nj = i + d[p][0], j + d[p][1]
            a[ni][nj] += 1
        elif mat[i][j] == '.' and num == 0:
            ans += 1
        elif mat[i][j] == '#' and num == 0:
            a[i][j] += 1
mx = 0
for i in range(1, n + 1):
    for j in range(1, m + 1):
        mx = max(mx, a[i][j])
print(ans + mx)
